import { migrate } from 'drizzle-orm/libsql/migrator'
import { existsSync } from 'node:fs'
import { join } from 'node:path'
import { logger } from '@/core/logger'
import { LOG } from '@/shared/constants'
import { client, db } from './index'

// Applies the committed migrations in `drizzle/` (generated by `npm run db:generate`).
// Run with `npm run db:migrate`; it reads DATABASE_URL like the app does.
const MIGRATIONS_FOLDER = 'drizzle'

const run = async (): Promise<void> => {
  if (!existsSync(join(MIGRATIONS_FOLDER, 'meta', '_journal.json'))) {
    logger.info(LOG.DATABASE.noMigrations)
    return
  }
  await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER })
  logger.info(LOG.DATABASE.migrated)
}

try {
  await run()
} finally {
  client.close()
}
